param([Parameter(Mandatory=$true)][string]$Root,[Parameter(Mandatory=$true)][int]$TargetPid,[string]$LogPath=(Join-Path $Root 'logs\run.log'),[string]$LedgerPath=(Join-Path $Root 'ledgers\stage.json'),[string]$ResultsPath=(Join-Path $Root 'results'),[string]$EventsPath=(Join-Path $Root 'events.jsonl'),[int]$IntervalSeconds=20,[int]$TailLines=8)
$OutputEncoding=[Console]::OutputEncoding=[System.Text.UTF8Encoding]::new($false)
function Read-Json($p){if(!(Test-Path -LiteralPath $p)){return $null};try{Get-Content -LiteralPath $p -Raw -ErrorAction Stop|ConvertFrom-Json}catch{$null}}
function Add-Event($type,$severity,$task,$summary){$e=[ordered]@{event_id=([guid]::NewGuid().ToString());timestamp=(Get-Date).ToUniversalTime().ToString('o');type=$type;severity=$severity;task=$task;summary=$summary};$d=Split-Path -Parent $EventsPath;if($d){New-Item -ItemType Directory -Force -Path $d|Out-Null};Add-Content -LiteralPath $EventsPath -Value ($e|ConvertTo-Json -Compress) -Encoding UTF8}
$lastCompleted=-1
while($true){Clear-Host;$ledger=Read-Json $LedgerPath;$total=0;if($ledger -and $ledger.candidate_ids){$total=@($ledger.candidate_ids).Count*$(if($ledger.seeds){@($ledger.seeds).Count}else{1})}elseif($ledger -and $ledger.jobs){$total=@($ledger.jobs).Count};$completed=0;if(Test-Path -LiteralPath $ResultsPath){$completed=@(Get-ChildItem -LiteralPath $ResultsPath -Filter '*.json' -File -ErrorAction SilentlyContinue|Where-Object{$r=Read-Json $_.FullName;$r -and $r.status -in @('completed','success')}).Count};$running=if($ledger -and $ledger.running){@($ledger.running).Count}else{0};$pending=if($total){[Math]::Max(0,$total-$completed-$running)}else{'?'};$pct=if($total){100*$completed/$total}else{0};$bar=('#'*[Math]::Round(45*$pct/100)).PadRight(45,'-');$proc=Get-Process -Id $TargetPid -ErrorAction SilentlyContinue;$state=if($proc){'运行中'}else{'已结束或未启动'};$cpu=if($proc){'{0:N1}s'-f $proc.CPU}else{'N/A'};$mem=if($proc){'{0:N0} MB'-f ($proc.WorkingSet64/1MB)}else{'N/A'};Write-Host "时间: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')";Write-Host "状态: $state PID: $TargetPid CPU: $cpu 内存: $mem";Write-Host ("进度: [{0}] {1:N1}% 完成: {2}/{3}"-f $bar,$pct,$completed,$(if($total){$total}else{'?'}));Write-Host "任务: completed=$completed running=$running pending=$pending";if($ledger.current_job){Write-Host "当前: $($ledger.current_job)"};Write-Host 'ETA: 按已完成任务平均耗时估算（仅供参考）';Write-Host 'GPU:';$gpu=nvidia-smi --query-gpu=utilization.gpu,memory.used,memory.total,temperature.gpu,power.draw --format=csv,noheader,nounits 2>$null;if($LASTEXITCODE -eq 0){$gpu}else{Write-Host 'GPU: 不可用'};Write-Host '日志尾部:';if(Test-Path -LiteralPath $LogPath){Get-Content -LiteralPath $LogPath -Tail $TailLines -ErrorAction SilentlyContinue}else{Write-Host '等待日志文件'};if($lastCompleted -ge 0 -and $completed -gt $lastCompleted){Add-Event 'task_completed' 'info' $ledger.current_job "完成数更新为 $completed/$total"};$lastCompleted=$completed;if(!$proc){Add-Event 'process_finished' 'info' '' '主进程已结束';break};Start-Sleep -Seconds $IntervalSeconds}
